"use client";

import { Button } from "@/components/ui/button";
import {
	AlertCircleIcon,
	FileArchiveIcon,
	FileIcon,
	FileSpreadsheetIcon,
	FileTextIcon,
	HeadphonesIcon,
	ImageIcon,
	Trash2Icon,
	UploadIcon,
	VideoIcon,
	XIcon,
} from "lucide-react";

import { formatBytes, useFileUpload } from "@/registry/ui-basic/hooks/usefileUpload";

// Create some dummy initial files
const initialFiles = [
	{
		name: "intro.zip",
		size: 252873,
		type: "application/zip",
		url: "https://example.com/intro.zip",
		id: "intro.zip-1744638436563-8u5xuls",
	},
	{
		name: "image-01.jpg",
		size: 1528737,
		type: "image/jpeg",
		url: "https://picsum.photos/1000/800?grayscale&random=1",
		id: "image-01-123456789",
	},
	{
		name: "audio.mp3",
		size: 1528737,
		type: "audio/mpeg",
		url: "https://example.com/audio.mp3",
		id: "audio-123456789",
	},
];

const getFileIcon = (file: { file: File | { type: string; name: string } }) => {
	const fileType = file.file instanceof File ? file.file.type : file.file.type;
	const fileName = file.file instanceof File ? file.file.name : file.file.name;

	const iconMap = {
		pdf: {
			icon: FileTextIcon,
			conditions: (type: string, name: string) =>
				type.includes("pdf") ||
				name.endsWith(".pdf") ||
				type.includes("word") ||
				name.endsWith(".doc") ||
				name.endsWith(".docx"),
		},
		archive: {
			icon: FileArchiveIcon,
			conditions: (type: string, name: string) =>
				type.includes("zip") ||
				type.includes("archive") ||
				name.endsWith(".zip") ||
				name.endsWith(".rar"),
		},
		excel: {
			icon: FileSpreadsheetIcon,
			conditions: (type: string, name: string) =>
				type.includes("excel") ||
				name.endsWith(".xls") ||
				name.endsWith(".xlsx"),
		},
		video: {
			icon: VideoIcon,
			conditions: (type: string) => type.includes("video/"),
		},
		audio: {
			icon: HeadphonesIcon,
			conditions: (type: string) => type.includes("audio/"),
		},
		image: {
			icon: ImageIcon,
			conditions: (type: string) => type.startsWith("image/"),
		},
	};

	for (const { icon: Icon, conditions } of Object.values(iconMap)) {
		if (conditions(fileType, fileName)) {
			return <Icon className="size-5 opacity-60" />;
		}
	}

	return <FileIcon className="size-5 opacity-60" />;
};

const getFilePreview = (file: {
	file: File | { type: string; name: string; url?: string };
}) => {
	const fileType = file.file instanceof File ? file.file.type : file.file.type;
	const fileName = file.file instanceof File ? file.file.name : file.file.name;

	const renderImage = (src: string) => (
		<img
			src={src}
			alt={fileName}
			className="size-full rounded-t-[inherit] object-cover"
		/>
	);

	return (
		<div className="bg-accent flex aspect-square items-center justify-center overflow-hidden rounded-t-[inherit]">
			{fileType.startsWith("image/") ? (
				file.file instanceof File ? (
					(() => {
						const previewUrl = URL.createObjectURL(file.file);
						return renderImage(previewUrl);
					})()
				) : file.file.url ? (
					renderImage(file.file.url)
				) : (
					<ImageIcon className="size-5 opacity-60" />
				)
			) : (
				getFileIcon(file)
			)}
		</div>
	);
};

export default function Component() {
	const maxSizeMB = 5;
	const maxSize = maxSizeMB * 1024 * 1024; // 5MB default
	const maxFiles = 6;

	const [
		{ files, isDragging, errors },
		{
			handleDragEnter,
			handleDragLeave,
			handleDragOver,
			handleDrop,
			openFileDialog,
			removeFile,
			clearFiles,
			getInputProps,
		},
	] = useFileUpload({
		multiple: true,
		maxFiles,
		maxSize,
		initialFiles,
	});

	return (
		<div className="flex flex-col gap-2">
			{/* Drop area */}
			<div
				onDragEnter={handleDragEnter}
				onDragLeave={handleDragLeave}
				onDragOver={handleDragOver}
				onDrop={handleDrop}
				data-dragging={isDragging || undefined}
				data-files={files.length > 0 || undefined}
				className="border-input data-[dragging=true]:bg-accent/50 has-[input:focus]:border-ring has-[input:focus]:ring-ring/50 relative flex min-h-52 flex-col items-center overflow-hidden rounded-xl border border-dashed p-4 transition-colors not-data-files:justify-center has-[input:focus]:ring-[3px]"
			>
				<input
					{...getInputProps()}
					className="sr-only"
					aria-label="Upload image file"
				/>
				{files.length > 0 ? (
					<div className="flex w-full flex-col gap-3">
						<div className="flex items-center justify-between gap-2">
							<h3 className="truncate text-sm font-medium">
								Files ({files.length})
							</h3>
							<div className="flex gap-2">
								<Button
									variant="outline"
									size="sm"
									onClick={openFileDialog}
								>
									<UploadIcon
										className="-ms-0.5 size-3.5 opacity-60"
										aria-hidden="true"
									/>
									Add files
								</Button>
								<Button
									variant="outline"
									size="sm"
									onClick={clearFiles}
								>
									<Trash2Icon
										className="-ms-0.5 size-3.5 opacity-60"
										aria-hidden="true"
									/>
									Remove all
								</Button>
							</div>
						</div>

						<div className="grid grid-cols-2 gap-4 md:grid-cols-3">
							{files.map((file) => (
								<div
									key={file.id}
									className="bg-background relative flex flex-col rounded-md border"
								>
									{getFilePreview(file)}
									<Button
										onClick={() => removeFile(file.id)}
										size="icon"
										className="border-background focus-visible:border-background absolute -top-2 -right-2 size-6 rounded-full border-2 shadow-none"
										aria-label="Remove image"
									>
										<XIcon className="size-3.5" />
									</Button>
									<div className="flex min-w-0 flex-col gap-0.5 border-t p-3">
										<p className="truncate text-[13px] font-medium">
											{file.file.name}
										</p>
										<p className="text-muted-foreground truncate text-xs">
											{formatBytes(file.file.size)}
										</p>
									</div>
								</div>
							))}
						</div>
					</div>
				) : (
					<div className="flex flex-col items-center justify-center px-4 py-3 text-center">
						<div
							className="bg-background mb-2 flex size-11 shrink-0 items-center justify-center rounded-full border"
							aria-hidden="true"
						>
							<ImageIcon className="size-4 opacity-60" />
						</div>
						<p className="mb-1.5 text-sm font-medium">
							Drop your files here
						</p>
						<p className="text-muted-foreground text-xs">
							Max {maxFiles} files ∙ Up to {maxSizeMB}MB
						</p>
						<Button
							variant="outline"
							className="mt-4"
							onClick={openFileDialog}
						>
							<UploadIcon
								className="-ms-1 opacity-60"
								aria-hidden="true"
							/>
							Select images
						</Button>
					</div>
				)}
			</div>

			{errors.length > 0 && (
				<div
					className="text-destructive flex items-center gap-1 text-xs"
					role="alert"
				>
					<AlertCircleIcon className="size-3 shrink-0" />
					<span>{errors[0]}</span>
				</div>
			)}

			<p
				aria-live="polite"
				role="region"
				className="text-muted-foreground mt-2 text-center text-xs"
			>
				Mixed content w/ card ∙{" "}
				<a
					href="https://github.com/origin-space/originui/tree/main/docs/use-file-upload.md"
					className="hover:text-foreground underline"
				>
					API
				</a>
			</p>
		</div>
	);
}

import * as React from "react";

import { cn } from "@/lib/utils";
import { Slot } from "@radix-ui/react-slot";
import { cva, type VariantProps } from "class-variance-authority";

const buttonVariants = cva(
	"inline-flex items-center justify-center whitespace-nowrap rounded-md text-sm text-white hover:text-gray-400 font-medium ring-offset-background transition-colors focus-visible:outline-hidden focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 disabled:pointer-events-none disabled:opacity-50",
	{
		variants: {
			variant: {
				simple:
					"bg-secondary relative z-10 bg-transparent hover:border-secondary hover:bg-secondary/50  border border-transparent dark:text-white text-sm md:text-sm transition font-medium duration-200  rounded-md px-4 py-2  flex items-center justify-center",
				default: "bg-primary text-primary-foreground hover:bg-primary/90",
				destructive:
					"bg-destructive text-destructive-foreground hover:bg-destructive/90",
				outline:
					"border border-input bg-background hover:bg-accent hover:text-accent-foreground",
				secondary:
					"bg-secondary text-secondary-foreground hover:bg-secondary/80",
				ghost: "hover:bg-accent hover:text-black hover:stroke-black dark:text-white text-black",
				link: "text-primary underline-offset-4 hover:underline",
			},
			size: {
				default: "h-10 px-4 py-2",
				sm: "h-9 rounded-md px-3",
				lg: "h-11 rounded-md px-8",
				icon: "h-10 w-10",
			},
		},
		defaultVariants: {
			variant: "default",
			size: "default",
		},
	}
);

export interface ButtonProps
	extends React.ButtonHTMLAttributes<HTMLButtonElement>,
		VariantProps<typeof buttonVariants> {
	asChild?: boolean;
}

const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(
	({ className, variant, size, asChild = false, ...props }, ref) => {
		const Comp = asChild ? Slot : "button";
		return (
			<Comp
				className={cn(buttonVariants({ variant, size, className }))}
				ref={ref}
				{...props}
			/>
		);
	}
);
Button.displayName = "Button";

export { Button, buttonVariants };

"use client"

import type React from "react"
import {
    useCallback,
    useRef,
    useState,
    type ChangeEvent,
    type DragEvent,
    type InputHTMLAttributes,
} from "react"

export type FileMetadata = {
    name: string
    size: number
    type: string
    url: string
    id: string
}

export type FileWithPreview = {
    file: File | FileMetadata
    id: string
    preview?: string
}

export type FileUploadOptions = {
    maxFiles?: number // Only used when multiple is true, defaults to Infinity
    maxSize?: number // in bytes
    accept?: string
    multiple?: boolean // Defaults to false
    initialFiles?: FileMetadata[]
    onFilesChange?: (files: FileWithPreview[]) => void // Callback when files change
    onFilesAdded?: (addedFiles: FileWithPreview[]) => void // Callback when new files are added
}

export type FileUploadState = {
    files: FileWithPreview[]
    isDragging: boolean
    errors: string[]
}

export type FileUploadActions = {
    addFiles: (files: FileList | File[]) => void
    removeFile: (id: string) => void
    clearFiles: () => void
    clearErrors: () => void
    handleDragEnter: (e: DragEvent<HTMLElement>) => void
    handleDragLeave: (e: DragEvent<HTMLElement>) => void
    handleDragOver: (e: DragEvent<HTMLElement>) => void
    handleDrop: (e: DragEvent<HTMLElement>) => void
    handleFileChange: (e: ChangeEvent<HTMLInputElement>) => void
    openFileDialog: () => void
    getInputProps: (
        props?: InputHTMLAttributes<HTMLInputElement>
    ) => InputHTMLAttributes<HTMLInputElement> & {
        ref: React.Ref<HTMLInputElement>
    }
}

export const useFileUpload = (
    options: FileUploadOptions = {}
): [FileUploadState, FileUploadActions] => {
    const {
        maxFiles = Infinity,
        maxSize = Infinity,
        accept = "*",
        multiple = false,
        initialFiles = [],
        onFilesChange,
        onFilesAdded,
    } = options

    const [state, setState] = useState<FileUploadState>({
        files: initialFiles.map((file) => ({
            file,
            id: file.id,
            preview: file.url,
        })),
        isDragging: false,
        errors: [],
    })

    const inputRef = useRef<HTMLInputElement>(null)

    const validateFile = useCallback(
        (file: File | FileMetadata): string | null => {
            if (file instanceof File) {
                if (file.size > maxSize) {
                    return `File "${file.name}" exceeds the maximum size of ${formatBytes(maxSize)}.`
                }
            } else {
                if (file.size > maxSize) {
                    return `File "${file.name}" exceeds the maximum size of ${formatBytes(maxSize)}.`
                }
            }

            if (accept !== "*") {
                const acceptedTypes = accept.split(",").map((type) => type.trim())
                const fileType = file instanceof File ? file.type || "" : file.type
                const fileExtension = `.${file instanceof File ? file.name.split(".").pop() : file.name.split(".").pop()}`

                const isAccepted = acceptedTypes.some((type) => {
                    if (type.startsWith(".")) {
                        return fileExtension.toLowerCase() === type.toLowerCase()
                    }
                    if (type.endsWith("/*")) {
                        const baseType = type.split("/")[0]
                        return fileType.startsWith(`${baseType}/`)
                    }
                    return fileType === type
                })

                if (!isAccepted) {
                    return `File "${file instanceof File ? file.name : file.name}" is not an accepted file type.`
                }
            }

            return null
        },
        [accept, maxSize]
    )

    const createPreview = useCallback(
        (file: File | FileMetadata): string | undefined => {
            if (file instanceof File) {
                return URL.createObjectURL(file)
            }
            return file.url
        },
        []
    )

    const generateUniqueId = useCallback((file: File | FileMetadata): string => {
        if (file instanceof File) {
            return `${file.name}-${Date.now()}-${Math.random().toString(36).substring(2, 9)}`
        }
        return file.id
    }, [])

    const clearFiles = useCallback(() => {
        setState((prev) => {
            // Clean up object URLs
            prev.files.forEach((file) => {
                if (
                    file.preview &&
                    file.file instanceof File &&
                    file.file.type.startsWith("image/")
                ) {
                    URL.revokeObjectURL(file.preview)
                }
            })

            if (inputRef.current) {
                inputRef.current.value = ""
            }

            const newState = {
                ...prev,
                files: [],
                errors: [],
            }

            onFilesChange?.(newState.files)
            return newState
        })
    }, [onFilesChange])

    const addFiles = useCallback(
        (newFiles: FileList | File[]) => {
            if (!newFiles || newFiles.length === 0) return

            const newFilesArray = Array.from(newFiles)
            const errors: string[] = []

            // Clear existing errors when new files are uploaded
            setState((prev) => ({ ...prev, errors: [] }))

            // In single file mode, clear existing files first
            if (!multiple) {
                clearFiles()
            }

            // Check if adding these files would exceed maxFiles (only in multiple mode)
            if (
                multiple &&
                maxFiles !== Infinity &&
                state.files.length + newFilesArray.length > maxFiles
            ) {
                errors.push(`You can only upload a maximum of ${maxFiles} files.`)
                setState((prev) => ({ ...prev, errors }))
                return
            }

            const validFiles: FileWithPreview[] = []

            newFilesArray.forEach((file) => {
                // Only check for duplicates if multiple files are allowed
                if (multiple) {
                    const isDuplicate = state.files.some(
                        (existingFile) =>
                            existingFile.file.name === file.name &&
                            existingFile.file.size === file.size
                    )

                    // Skip duplicate files silently
                    if (isDuplicate) {
                        return
                    }
                }

                // Check file size
                if (file.size > maxSize) {
                    errors.push(
                        multiple
                            ? `Some files exceed the maximum size of ${formatBytes(maxSize)}.`
                            : `File exceeds the maximum size of ${formatBytes(maxSize)}.`
                    )
                    return
                }

                const error = validateFile(file)
                if (error) {
                    errors.push(error)
                } else {
                    validFiles.push({
                        file,
                        id: generateUniqueId(file),
                        preview: createPreview(file),
                    })
                }
            })

            // Only update state if we have valid files to add
            if (validFiles.length > 0) {
                // Call the onFilesAdded callback with the newly added valid files
                onFilesAdded?.(validFiles)

                setState((prev) => {
                    const newFiles = !multiple
                        ? validFiles
                        : [...prev.files, ...validFiles]
                    onFilesChange?.(newFiles)
                    return {
                        ...prev,
                        files: newFiles,
                        errors,
                    }
                })
            } else if (errors.length > 0) {
                setState((prev) => ({
                    ...prev,
                    errors,
                }))
            }

            // Reset input value after handling files
            if (inputRef.current) {
                inputRef.current.value = ""
            }
        },
        [
            state.files,
            maxFiles,
            multiple,
            maxSize,
            validateFile,
            createPreview,
            generateUniqueId,
            clearFiles,
            onFilesChange,
            onFilesAdded,
        ]
    )

    const removeFile = useCallback(
        (id: string) => {
            setState((prev) => {
                const fileToRemove = prev.files.find((file) => file.id === id)
                if (
                    fileToRemove &&
                    fileToRemove.preview &&
                    fileToRemove.file instanceof File &&
                    fileToRemove.file.type.startsWith("image/")
                ) {
                    URL.revokeObjectURL(fileToRemove.preview)
                }

                const newFiles = prev.files.filter((file) => file.id !== id)
                onFilesChange?.(newFiles)

                return {
                    ...prev,
                    files: newFiles,
                    errors: [],
                }
            })
        },
        [onFilesChange]
    )

    const clearErrors = useCallback(() => {
        setState((prev) => ({
            ...prev,
            errors: [],
        }))
    }, [])

    const handleDragEnter = useCallback((e: DragEvent<HTMLElement>) => {
        e.preventDefault()
        e.stopPropagation()
        setState((prev) => ({ ...prev, isDragging: true }))
    }, [])

    const handleDragLeave = useCallback((e: DragEvent<HTMLElement>) => {
        e.preventDefault()
        e.stopPropagation()

        if (e.currentTarget.contains(e.relatedTarget as Node)) {
            return
        }

        setState((prev) => ({ ...prev, isDragging: false }))
    }, [])

    const handleDragOver = useCallback((e: DragEvent<HTMLElement>) => {
        e.preventDefault()
        e.stopPropagation()
    }, [])

    const handleDrop = useCallback(
        (e: DragEvent<HTMLElement>) => {
            e.preventDefault()
            e.stopPropagation()
            setState((prev) => ({ ...prev, isDragging: false }))

            // Don't process files if the input is disabled
            if (inputRef.current?.disabled) {
                return
            }

            if (e.dataTransfer.files && e.dataTransfer.files.length > 0) {
                // In single file mode, only use the first file
                if (!multiple) {
                    const file = e.dataTransfer.files[0]
                    addFiles([file])
                } else {
                    addFiles(e.dataTransfer.files)
                }
            }
        },
        [addFiles, multiple]
    )

    const handleFileChange = useCallback(
        (e: ChangeEvent<HTMLInputElement>) => {
            if (e.target.files && e.target.files.length > 0) {
                addFiles(e.target.files)
            }
        },
        [addFiles]
    )

    const openFileDialog = useCallback(() => {
        if (inputRef.current) {
            inputRef.current.click()
        }
    }, [])

    const getInputProps = useCallback(
        (props: InputHTMLAttributes<HTMLInputElement> = {}) => {
            return {
                ...props,
                type: "file" as const,
                onChange: handleFileChange,
                accept: props.accept || accept,
                multiple: props.multiple !== undefined ? props.multiple : multiple,
                ref: inputRef,
            }
        },
        [accept, multiple, handleFileChange]
    )

    return [
        state,
        {
            addFiles,
            removeFile,
            clearFiles,
            clearErrors,
            handleDragEnter,
            handleDragLeave,
            handleDragOver,
            handleDrop,
            handleFileChange,
            openFileDialog,
            getInputProps,
        },
    ]
}

// Helper function to format bytes to human-readable format
export const formatBytes = (bytes: number, decimals = 2): string => {
    if (bytes === 0) return "0 Bytes"

    const k = 1024
    const dm = decimals < 0 ? 0 : decimals
    const sizes = ["Bytes", "KB", "MB", "GB", "TB", "PB", "EB", "ZB", "YB"]

    const i = Math.floor(Math.log(bytes) / Math.log(k))

    return Number.parseFloat((bytes / Math.pow(k, i)).toFixed(dm)) + sizes[i]
}
